-- Rifts World Book 35: Megaverse in Flames, Lord Kreelo's Blood Energy weapons and body armors (printed 114-116)
-- 6 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~345-megaverse-in-flames-kreelo-arms-gear.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
--
-- Four Blood Energy weapons and two body armors. Every damage, cost and M.D.C.
-- figure was read off a render of its page. The book's shared payload rule for
-- all Blood Energy weapons (printed 114) is restated in each weapon's description.
-- A RANGE IS STORED BY ITS LOW END; cost_note gives the whole range. The four
-- weapons print a black-market range only; the two armors print Kreelo's own
-- price for a standard suit, the large suit and the enchantments in cost_note.
-- M.D.C. THAT IS ROLLED (Flesh Armor 3D6+50, Bone Armor 1D6x10+90 main body)
-- leaves mdc empty, and each location is stated in the description.
-- Not the same item, left alone: mutant-bone-armor (Madhaven) and
-- ew-skin-and-bone-armor (Dinosaur Swamp).

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('bew-wrist-blaster', 'BEW Wrist Blaster', 'rifts', 'weapon', 3, 35000, '35,000-50,000 credits at black markets such as the Splynn D-Market and Diablo Island; not sold openly on Earth.', '3D6 M.D.', 1, '900 feet (274 m)', '30 shots; each refill draws 20 S.D.C., 5 H.P. or 20 M.D.C. from the wearer', 'Single shots; one attack per blast', NULL, NULL, NULL, 'Lord Kreelo''s Megaverse Armaments, Blood Energy Weapon series. The cheapest and most mass-produced of the line: a skull on a length of ribcage or spine that clamps onto the forearm, sinks needles into the wielder and fires on his blood. Every Blood Energy weapon follows one rule: once fixed to a body it cannot be taken off until the host dies, and it then frees itself for the next host. When its shots run out it at once takes 20 S.D.C., 5 H.P. or 20 M.D.C. from the host for a fresh full payload, and keeps doing so for as long as he fires, so a careless shooter can bleed himself to death. H.P. or M.D.C. lost this way do not Bio-Regenerate until he has gone 30 minutes without firing.', 'Rifts World Book 35: Megaverse in Flames p.114', NULL),
  ('bew-shoulder-blaster', 'BEW Shoulder Blaster', 'rifts', 'weapon', 6, 50000, '50,000-70,000 credits at black markets such as the Splynn D-Market and Diablo Island; not sold openly on Earth.', '4D6 M.D.', 1, '1,800 feet (549 m)', '22 shots; each refill draws 20 S.D.C., 5 H.P. or 20 M.D.C. from the wearer', 'Single shots', NULL, NULL, NULL, 'Lord Kreelo''s Megaverse Armaments, Blood Energy Weapon series. A hands-free gun on a swivel mount at the shoulder that can face front, rear or either side, with 45 degrees of elevation either way. A monocle sight drops over one eye; the gun follows the wearer''s gaze and fires on a spoken word. Every Blood Energy weapon follows one rule: once fixed to a body it cannot be taken off until the host dies, and it then frees itself for the next host. When its shots run out it at once takes 20 S.D.C., 5 H.P. or 20 M.D.C. from the host for a fresh full payload, and keeps doing so for as long as he fires, so a careless shooter can bleed himself to death. H.P. or M.D.C. lost this way do not Bio-Regenerate until he has gone 30 minutes without firing.', 'Rifts World Book 35: Megaverse in Flames p.114', NULL),
  ('bew-blood-rifle', 'BEW Blood Rifle', 'rifts', 'weapon', 7, 65000, '65,000-90,000 credits at black markets such as the Splynn D-Market and Diablo Island; not sold openly on Earth.', '5D6 M.D. per blast; in melee 1D6 M.D. per extended blade, 4D6 M.D. with all four out', 1, '2,000 feet (610 m)', '16 shots; each refill draws 20 S.D.C., 5 H.P. or 20 M.D.C. from the wearer', 'Single shots', NULL, NULL, NULL, 'Lord Kreelo''s Megaverse Armaments, Blood Energy Weapon series. A larger cousin of the Wrist Blaster that sheathes the forearm to the elbow and folds out over more of the arm when stowed, leaving the hand free. Simple enough that a minion with no W.P. Energy Rifle still gets +1 to strike with it. Four retractable blades, any number of which may be run out, let it slash and stab in melee. Every Blood Energy weapon follows one rule: once fixed to a body it cannot be taken off until the host dies, and it then frees itself for the next host. When its shots run out it at once takes 20 S.D.C., 5 H.P. or 20 M.D.C. from the host for a fresh full payload, and keeps doing so for as long as he fires, so a careless shooter can bleed himself to death. H.P. or M.D.C. lost this way do not Bio-Regenerate until he has gone 30 minutes without firing.', 'Rifts World Book 35: Megaverse in Flames p.114-115', NULL),
  ('bew-blood-cannon', 'BEW Blood Cannon', 'rifts', 'weapon', 200, 80000, '80,000-120,000 credits at black markets such as the Splynn D-Market and Diablo Island; not sold openly on Earth.', '1D6x10 M.D.', 1, '2,500 feet (762 m)', '8 shots; each refill draws 20 S.D.C., 5 H.P. or 20 M.D.C. from the host or mount', 'Single shots', NULL, NULL, NULL, 'Lord Kreelo''s Megaverse Armaments, Blood Energy Weapon series. Effectively demonic artillery: too big for anything but the largest demons and Sub-Demons such as Gurgoyles to carry, and those must crouch or go on all fours to aim it, so it is usually strapped to a Netherbeast or War Steed instead. Deevils also build it into war barges, fed from a Blood Pool. It aims with the Shoulder Blaster''s monocle, firing where its gunner looks. Mounted on a beast, it drinks the animal''s blood, and a rider who misjudges can kill his mount; once the beast is down to 20% of its H.P. or M.D.C. it loses one melee attack and 30% of its Spd. Every Blood Energy weapon follows one rule: once fixed to a body it cannot be taken off until the host dies, and it then frees itself for the next host. When its shots run out it at once takes 20 S.D.C., 5 H.P. or 20 M.D.C. from the host for a fresh full payload, and keeps doing so for as long as it fires. H.P. or M.D.C. lost this way do not Bio-Regenerate until 30 minutes have passed without firing.', 'Rifts World Book 35: Megaverse in Flames p.115', NULL),
  ('flesh-armor', 'Flesh Armor', 'rifts', 'armor', 10, 45000, '45,000 credits for a standard suit; 75,000 for a large suit (11-22 ft/3.3-6.7 m). Each enchantment, two at most, adds 15,000.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Lord Kreelo''s Megaverse Armaments. Light armor for clandestine operations: the skins of slain mortals, Soulmancy-enchanted into a thin, supple bodysuit worn like a wetsuit. Its colour depends on whoever was skinned for it; bodies up to 12 hours dead can be used, and Ghouls strip the fallen on battlefields for it. A standard suit fits a wearer 5 to 10 ft (1.5-3 m) tall and stretches or shrinks by up to half to fit. Location M.D.C.: 30 head, 25 per arm, 35 per leg, 3D6+50 main body; the main body is rolled, so the mdc column is left empty. Excellent mobility, no penalty to physical skills. Not environmental armor. Up to two enchantments may be bought, each working as the spell of that name for 20 minutes a use, three uses a day: Breathe Without Air, Chameleon, Climb, Escape, Swim as a Fish: Superior, and Superhuman Endurance, Speed or Strength.', 'Rifts World Book 35: Megaverse in Flames p.115-116', NULL),
  ('bone-armor', 'Bone Armor', 'rifts', 'armor', 50, 95000, '95,000 credits for a standard suit; 140,000 for a large suit (11-22 ft/3.4-6.7 m). Each enchantment, four at most, adds 15,000.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Lord Kreelo''s Megaverse Armaments. Heavy combat armor of mortal bones, sorted by Ghouls and Nasu, fused together and hardened by Soulmancy into a fairly flexible hard suit. Only the helmet is standard, always a skull, though the skull may be human, D-Bee, animal or horned and demonic. A standard suit fits a wearer 5 to 10 ft (1.5-3 m) tall. Location M.D.C.: 50 head/helmet, 45 per arm, 65 per leg, 1D6x10+90 main body; the main body is rolled, so the mdc column is left empty. Poor mobility: -15% to skills that need free movement, such as Acrobatics, Climbing, Gymnastics, Pick Pockets, Prowl and Swimming. Not environmental armor. Up to four enchantments may be bought, each working as the spell of that name for 30 minutes a use, three uses a day: Lantern Light, Levitation, Magic Shield, Impervious to Fire, Breathe Without Air, Chameleon, Cleanse, Climb, Escape, Swim as a Fish: Superior, and Superhuman Endurance, Speed or Strength.', 'Rifts World Book 35: Megaverse in Flames p.116', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 6 gear rows are in' AS assertion, count(*) AS got, 6 AS want
  FROM gear WHERE slug IN ('bew-wrist-blaster', 'bew-shoulder-blaster', 'bew-blood-rifle', 'bew-blood-cannon', 'flesh-armor', 'bone-armor') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~345-megaverse-in-flames-kreelo-arms-gear.sql');
